import AdminFormDesigner from "@/components/FormDesigner/AdminFormDesigner.vue";
export default {
  components: {
    AdminFormDesigner
  },
  props: {
    formedition: Boolean
  },
  data() {
    return {
      componentCheck: 0
    };
  },
  watch: {
    formedition: {
      async handler() {
        if (this.formedition == true) {
          this.componentCheck += 1;
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    error_info(val) {
      this.$emit("errorMsg", val);
    },
    success_info(val) {
      this.$emit("successMsg", val);
    }
  }
};
